mapper.update:
CREATE INDEX ${tableName}_IDX1 ON ${tableName} (GROUP_KEY, SENDABLE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName} (STATUS, REQDATE, SENDABLE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName} (REQDATE);

UPDATE ${tableName}
SET
    STATUS = #{parameter.imageStatus}
    , SENDABLE = #{parameter.sendable}
    , IMG_ID = #{parameter.fileId}
    , RSLT = #{parameter.doneCode}
    , RSLTDESC = #{parameter.doneCodeDescription}
    , RPTDATE = CONVERT(DATETIME,STUFF(STUFF(STUFF(#{parameter.doneDate},9,0,' '),12,0,':'),15,0,':'))
WHERE
    IMGKEY IS NULL
    IMGKEY = #{parameter.key}
